"use client";

import Link from 'next/link';
import { useAppStore } from '@/lib/store';
import { Image as ImageIcon, BookOpen, FileText, PenTool, Hash } from 'lucide-react';

export function QuickLinks() {
  const { parentCategories } = useAppStore();

  const getIcon = (id: string) => {
    switch (id) {
      case 'illustrations': return ImageIcon;
      case 'comics-long': return BookOpen;
      case 'comics-short': return FileText;
      default: return Hash;
    }
  };

  const getHref = (id: string) => {
    switch (id) {
      case 'illustrations': return '/illustrations';
      case 'comics-long': return '/comics/long';
      case 'comics-short': return '/comics/short';
      default: return `/${id}`;
    }
  };

  const getDescription = (id: string) => {
    switch (id) {
      case 'illustrations': return '감성적인 비주얼 작업';
      case 'comics-long': return '연재와 기록을 함께';
      case 'comics-short': return '작품을 읽어보세요';
      default: return '작품을 감상하세요';
    }
  };

  return (
    <div className="mt-8 grid grid-cols-2 md:grid-cols-3 gap-3">
      {Object.entries(parentCategories).map(([id, label]) => {
        const Icon = getIcon(id);
        return (
          <Link
            key={id}
            href={getHref(id)}
            className="group rounded-2xl border border-blue-600/10 bg-white/90 p-4 shadow-sm hover:border-blue-600/30 hover:bg-blue-50/50 transition-all flex flex-col justify-between"
          >
            <div>
              <div className="text-sm font-bold text-blue-900 group-hover:text-blue-700 flex items-center justify-between">
                {label}
                <Icon className="h-4 w-4 opacity-50 group-hover:opacity-100" />
              </div>
              <div className="mt-1 text-xs leading-5 text-slate-500 group-hover:text-slate-700">{getDescription(id)}</div>
            </div>
          </Link>
        );
      })}

      <Link
        href="/commission"
        className="group rounded-2xl border border-blue-600/10 bg-white/90 p-4 shadow-sm hover:border-blue-600/30 hover:bg-blue-50/50 transition-all flex flex-col justify-between"
      >
        <div>
          <div className="text-sm font-bold text-blue-900 group-hover:text-blue-700 flex items-center justify-between">
            커미션
            <PenTool className="h-4 w-4 opacity-50 group-hover:opacity-100" />
          </div>
          <div className="mt-1 text-xs leading-5 text-slate-500 group-hover:text-slate-700">외주 안내 및 신청</div>
        </div>
      </Link>
    </div>
  );
}
