"use client";

import { useEffect, useState } from 'react';
import { useAppStore } from '@/lib/store';
import { MediaRenderer } from '@/components/media-renderer';

export function IntroOverlay() {
  const [showIntro, setShowIntro] = useState(true);
  const [fadingOut, setFadingOut] = useState(false);
  const { profile } = useAppStore();

  useEffect(() => {
    // Prevent scrolling while intro is visible
    if (showIntro && !fadingOut) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
  }, [showIntro, fadingOut]);

  const handleEnter = () => {
    if (fadingOut) return;
    setFadingOut(true);
    setTimeout(() => {
      setShowIntro(false);
    }, 800); // Wait for fade-out animation to finish
  };

  if (!showIntro) return null;

  return (
    <div
      onClick={handleEnter}
      className={`fixed inset-0 z-[100] flex flex-col justify-center items-center cursor-pointer transition-opacity duration-1000 ease-in-out ${
        fadingOut ? 'opacity-0 pointer-events-none' : 'opacity-100'
      }`}
    >
      {/* Background Image/Color */}
      <div className="absolute inset-0 z-0 bg-background/95">
        {profile.introBackgroundImage && (
          <MediaRenderer 
            src={profile.introBackgroundImage} 
            alt="Intro Background" 
            className="w-full h-full object-cover opacity-50 select-none pointer-events-none"
          />
        )}
      </div>

      {/* Main Content Container to animate rising up slightly */}
      <div 
        className={`relative z-10 flex flex-col items-center justify-center transition-all duration-1000 ease-in-out transform ${
          fadingOut ? '-translate-y-8' : 'translate-y-0'
        }`}
      >
        {/* Logo or Text */}
        <div className="flex flex-col items-center gap-6 animate-in fade-in zoom-in-95 duration-1000">
          <h1 className="text-5xl md:text-7xl font-bold tracking-tighter text-foreground drop-shadow-lg">
            JYAMONG
          </h1>
          <p className="text-lg md:text-xl text-muted-foreground tracking-[0.3em] font-medium drop-shadow-md">
            PORTFOLIO
          </p>
        </div>

        {/* Enter Text Instruction */}
        <div className="mt-32 text-muted-foreground/80 tracking-[0.2em] text-sm uppercase animate-in fade-in slide-in-from-bottom-5 duration-1000 delay-500 fill-mode-both font-medium">
          - Click anywhere to enter -
        </div>  
      </div>
    </div>
  );
}
