"use client";

import { useAppStore } from "@/lib/store";
import { FileText, ImageIcon } from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";
import { ko } from "date-fns/locale";

export function HomeContent() {
  const { comics, illustrations, profile } = useAppStore();

  const combined = [
    ...illustrations.map(i => ({ ...i, itemType: 'illustration' })),
    ...comics.map(c => ({ ...c, itemType: 'comic' }))
  ].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  const latestPosts = combined.slice(0, 5);

  return (
    <div className="grid gap-6 lg:grid-cols-[1fr_1fr]">
      {/* Notice (공지사항) */}
      <div className="flex flex-col h-full rounded-[2rem] border border-slate-900/10 bg-slate-950 p-6 text-white shadow-[0_18px_50px_rgba(15,23,42,0.18)]">
        <p className="text-xs font-semibold uppercase tracking-[0.28em] text-white/60">Notices</p>
        <h3 className="mt-3 text-2xl font-black tracking-tight">공지사항</h3>
        
        <div className="mt-6 flex-1 bg-white/5 rounded-2xl p-5 border border-white/10 backdrop-blur-sm overflow-y-auto max-h-[300px] text-sm leading-8 text-white/80 whitespace-pre-wrap flex flex-col gap-2">
          {profile.notice || "등록된 공지사항이 없습니다.\n프로필 편집에서 공지사항을 작성해주세요."}
        </div>
      </div>

      {/* Latest Posts (최신 게시글) */}
      <div className="rounded-[2rem] border border-slate-900/10 bg-white/85 p-6 shadow-[0_18px_50px_rgba(15,23,42,0.06)] backdrop-blur-sm sm:p-7">
        <div className="mb-5 flex items-end justify-between gap-3 border-b border-slate-100 pb-4">
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.28em] text-slate-500">Latest Posts</p>
            <h3 className="mt-1 text-2xl font-black tracking-tight text-slate-950">최신 게시글</h3>
          </div>
        </div>

        <div className="space-y-4">
          {latestPosts.length > 0 ? (
            latestPosts.map((post) => (
              <Link
                key={post.id}
                href={
                  post.itemType === 'illustration'
                    ? '/illustrations'
                    : `/comics/${'type' in post ? post.type : 'short'}`
                }
                className="group flex items-center gap-4 rounded-xl p-3 hover:bg-blue-50/50 transition-colors"
              >
                <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-lg bg-slate-100 group-hover:bg-white text-slate-400 group-hover:text-blue-500 shadow-sm transition-colors border border-slate-200 group-hover:border-blue-200">
                  {post.itemType === 'illustration' ? <ImageIcon className="h-5 w-5" /> : <FileText className="h-5 w-5" />}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-slate-900 truncate group-hover:text-blue-700 transition-colors">
                    {post.title}
                  </p>
                  <p className="text-xs text-slate-500 mt-1">
                    {post.itemType === 'illustration' ? '일러스트' : '웹툰/로그'} · {formatDistanceToNow(new Date(post.createdAt), { addSuffix: true, locale: ko })}
                  </p>
                </div>
              </Link>
            ))
          ) : (
            <p className="text-sm text-slate-500 text-center py-6">새로운 게시글이 없습니다.</p>
          )}
        </div>
      </div>
    </div>
  );
}
