"use client";

import { useState, useEffect } from "react";
import { useAppStore } from "@/lib/store";
import { ChevronLeft, ChevronRight, Eye } from "lucide-react";
import Link from "next/link";

export function FeaturedSlider() {
  const { comics, illustrations } = useAppStore();
  const [currentIndex, setCurrentIndex] = useState(0);

  // 일러스트와 만화를 합치고 실제 조회수(views) 기준으로 상위 5개를 추출
  const combined = [
    ...illustrations.map(i => ({ ...i, itemType: 'illustration' })),
    ...comics.map(c => ({ ...c, itemType: 'comic' }))
  ];
  
  const topFeatured = combined
    .map(item => ({
      ...item,
      actualViews: item.views || 0 
    }))
    .sort((a, b) => b.actualViews - a.actualViews)
    .slice(0, 5);

  useEffect(() => {
    if (topFeatured.length <= 1) return;
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % topFeatured.length);
    }, 5000);
    return () => clearInterval(timer);
  }, [topFeatured.length]);

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev === 0 ? topFeatured.length - 1 : prev - 1));
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % topFeatured.length);
  };

  if (topFeatured.length === 0) {
    return (
      <div className="flex h-full w-full items-center justify-center bg-slate-50 dark:bg-slate-900 rounded-xl">
        <p className="text-sm font-medium text-slate-400">등록된 작품이 없습니다.</p>
      </div>
    );
  }

  const currentItem = topFeatured[currentIndex];
  // 링크 주소 만들기
  const linkHref = currentItem.itemType === 'illustration' 
    ? `/illustrations/${currentItem.category || ''}`
    : `/comics/${(currentItem as any).type}/${currentItem.category || ''}`;

  const thumbnailUrl = 'thumbnailUrl' in currentItem && currentItem.thumbnailUrl 
    ? currentItem.thumbnailUrl 
    : ('images' in currentItem && currentItem.images[0] ? currentItem.images[0] : "/api/placeholder/400/600");

  return (
    <div className="relative w-full h-full min-h-[300px] md:min-h-[400px] rounded-2xl overflow-hidden group">
      {topFeatured.map((item, index) => {
        const isActive = index === currentIndex;
        const imgUrl = 'thumbnailUrl' in item && item.thumbnailUrl 
          ? item.thumbnailUrl 
          : ('images' in item && item.images[0] ? item.images[0] : "/api/placeholder/400/600");
          
        return (
          <div 
            key={item.id} 
            className={`absolute inset-0 transition-opacity duration-1000 ${isActive ? 'opacity-100 z-10' : 'opacity-0 z-0'}`}
          >
            <Link href={
              item.itemType === 'illustration' 
                ? `/illustrations/${item.category || ''}`
                : `/comics/${(item as any).type}/${item.category || ''}`
            } className="absolute inset-0 block group cursor-pointer">
              {/* Full background image fit */}
              <img src={imgUrl} alt={item.title} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" />
              
              {/* Overlay for text */}
              <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent p-6 text-white">
                <div className="mb-2 flex items-center gap-1.5 text-xs font-bold px-2 py-1 bg-white/20 backdrop-blur-md rounded-full w-fit">
                  <span className="text-blue-300">TOP {index + 1}</span>
                </div>
                <h3 className="text-xl md:text-2xl font-black leading-tight line-clamp-1">{item.title}</h3>
                <div className="mt-2 flex items-center gap-1.5 text-sm text-white/80">
                  <Eye className="w-4 h-4" />
                  <span>{item.actualViews.toLocaleString()} 조회</span>
                </div>
              </div>
            </Link>
          </div>
        );
      })}

      {/* Navigation Arrows */}
      {topFeatured.length > 1 && (
        <>
          <button
            onClick={prevSlide}
            className="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center rounded-full bg-white/20 hover:bg-white/40 text-white backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all z-20"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <button
            onClick={nextSlide}
            className="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center rounded-full bg-white/20 hover:bg-white/40 text-white backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-all z-20"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </>
      )}

      {/* Pagination Dots */}
      <div className="absolute bottom-4 left-0 right-0 z-20 flex justify-center gap-1.5">
        {topFeatured.map((_, idx) => (
          <button
            key={idx}
            onClick={() => setCurrentIndex(idx)}
            className={`transition-all rounded-full h-1.5 ${
              idx === currentIndex ? "w-4 bg-white" : "w-1.5 bg-white/40 hover:bg-white/60"
            }`}
          />
        ))}
      </div>
    </div>
  );
}