"use client";

import { useAppStore } from "@/lib/store";

export function HomeIntroText() {
  const { profile } = useAppStore();

  return (
    <>
      <h2 className="mt-6 text-4xl font-black tracking-tight text-slate-950 sm:text-5xl lg:text-6xl whitespace-pre-wrap leading-tight">
        {profile.greeting || "안녕하세요,\n일러스트레이터 쟈몽입니다."}
      </h2>
      <div className="mt-5 max-w-lg text-base leading-8 text-slate-600 sm:text-lg whitespace-pre-wrap">
        {profile.bio || "빛과 온도를 담아내는 일러스트와 서사가 있는 만화를 그립니다.\n이 공간에서 다양한 작업물과 기록들을 둘러보세요."}
      </div>
    </>
  );
}
